#include <bits/stdc++.h>

#define push_back_zz z
using namespace std;
using LL = long long;
const int MOD = 1e9+7;

int fast_power(int base, int exp, int mod, int result=1) {
    for(; exp; exp>>=1, base=(LL)base*base%mod) if(exp & 1) result = (LL)result * base % mod;
    return result;
}

const int MAXN = 1<<7;
int p_array[MAXN][MAXN];
int pro_array[MAXN][MAXN];
int pop_count_arr[MAXN];
INT q_vals_arr[MAXN][MAXN];
int n;
int id_map[MAXN];
vector<int> group_by_pop[MAXN];
map<pair<int, LL>, int> memo_map;

inline void add_modulo(int &a, int b) {a+=b; if(a>=MOD) a -= MOD;}

int recursive(int idx, LL state) {
    if(state == 0) return 0;
    if(idx == n) return 1;
    if(memo_map.count({idx, state})) return memo_map[{idx, state}];
    int total=0;
    for(int subset=1; subset<(1<<n); ++subset) {
        LL new_state=0;
        for(int k=0; k<(int)group_by_pop[idx].size(); ++k) {
            if(!(state & (1LL<<k))) continue;
            int c=group_by_pop[idx][k];
            int nxt=subset - (subset & c);
            new_state |= q_vals_arr[c][nxt];
        }
        add_modulo(total, (LL)pro_array[idx][subset] * recursive(idx+1, new_state) % MOD);
    }
    return memo_map[{idx, state}] = total;
}

int main() {
#ifndef ONLINE_JUDGE
    freopen("in.in", "r", stdin);
    freopen("out.out", "w", stdout);
#endif
    scanf("%d", &n);
    int inv_100 = power(100, MOD-2, MOD);
    for(int i=0; i<n; i++) {
        for(int j=0; j<n; j++) {
            scanf("%d", p_array[i]+j);
            p_array[i][j] = (LL)p_array[i][j] * inv_100 % MOD;
        }
    }
    for(int i=0; i<n; i++) {
        for(int j=0; j<(1<<n); j++) {
            pro_array[i][j] = 1;
            for(int k=0; k<n; k++) {
                if((j>>k)&1) {
                    pro_array[i][j] = (LL)pro_array[i][j] * p_array[i][k] % MOD;
                } else {
                    pro_array[i][j] = (LL)pro_array[i][j] * (MOD+1 - p_array[i][k]) % MOD;
                }
            }
        }
    }
    for(int i=0; i<(1<<n); i++) pop_count_arr[i]=__builtin_popcount(i);
    for(int i=0; i<(1<<n); i++) {
        group_by_pop[pop_count_arr[i]].push_back(i);
        id_map[i] = (int)group_by_pop[pop_count_arr[i]].size() - 1;
    }
    for(int i=0; i<(1<<n); i++) {
        for(int j=0; j<n; j++) {
            if(!((i>>j)&1)) q_vals_arr[i][1<<j]=1LL<<id_map[i|(1<<j)];
        }
        for(int j=0; j<(1<<n); j++) {
            q_vals_arr[i][j]=q_vals_arr[i][j&-j]|q_vals_arr[i][j^(j&-j)];
        }
    }
    cout << recursive(0, 1) << endl;
}
